<script setup lang="ts">
import type { Page, Unit, Station } from '~/utils/types'
const { admin } = useSession(); const api = useApi()
const units = ref<Unit[]>([]); const cursor = ref<string | null>(); const stations = ref<Station[]>([]); const error = ref<unknown>(); const message = ref(''); const loading = ref(false); const saving = ref(false)
const edit = ref<Unit | null>(null); const form = reactive({ code: '', name: '', is_active: false, reason: '' }); const stationForm = reactive({ unit_id: '', code: '', name: '' })
async function load(more = false) { if (!admin.value) return; loading.value = true; error.value = undefined; try { const page = await api.get<Page<Unit>>(`/units?limit=100${more && cursor.value ? `&cursor=${encodeURIComponent(cursor.value)}` : ''}`); units.value = more ? [...units.value, ...page.items] : page.items; cursor.value = page.next_cursor; stations.value = (await api.get<Page<Station>>('/stations')).items } catch (e) { error.value = e } finally { loading.value = false } }
function select(unit?: Unit) { edit.value = unit || null; Object.assign(form, { code: unit?.code || '', name: unit?.name || '', is_active: unit?.is_active || false, reason: '' }); message.value = '' }
async function save() { saving.value = true; error.value = undefined; message.value = ''; try { if (edit.value) await api.command(`/units/${edit.value.id}`, { name: form.name.trim(), is_active: form.is_active, expected_version: edit.value.version, reason: form.reason.trim() }, 'PATCH'); else await api.command('/units', { code: form.code.trim(), name: form.name.trim() }); select(); message.value = 'บันทึกหน่วยงานแล้ว หน่วยงานใหม่จะเปิดใช้งานเมื่อแต่งตั้งผู้ดูแล'; await load() } catch (e) { error.value = e } finally { saving.value = false } }
async function createStation() { saving.value = true; error.value = undefined; try { await api.command('/stations', { ...stationForm, code: stationForm.code.trim(), name: stationForm.name.trim() }); Object.assign(stationForm, { code:'', name:'' }); message.value = 'เพิ่ม Station แล้ว'; await load() } catch (e) { error.value = e } finally { saving.value = false } }
onMounted(() => load())
</script>
<template><div class="page-head"><div><h1>จัดการหน่วยงาน</h1><p>เพิ่ม Unit ก่อนแต่งตั้งผู้ดูแลหน่วยงาน ระบบจะเปิดใช้งาน Unit พร้อมการแต่งตั้ง</p></div></div><Feedback v-if="!admin" :error="new Error('เฉพาะผู้ดูแลส่วนกลางเท่านั้น')" /><template v-else><Feedback :error="error" :message="message" /><div class="split"><section class="panel"><div class="page-head"><h2>ทะเบียนหน่วยงาน</h2><button type="button" class="text-link" @click="load()">โหลดล่าสุด</button></div><UProgress v-if="loading" /><div v-if="!units.length && !loading" class="empty">ยังไม่มีหน่วยงาน เริ่มเพิ่มหน่วยงานด้านข้าง</div><div class="table-wrap"><table v-if="units.length"><thead><tr><th>หน่วยงาน</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr v-for="unit in units" :key="unit.id"><td><div class="row-title">{{ unit.name }}</div><small>{{ unit.code }}</small></td><td><StatusTag :value="unit.provisioning_status" /><p v-if="!unit.is_active" class="hint">ยังไม่เปิดใช้งาน</p></td><td><button type="button" class="text-link" @click="select(unit)">แก้ไข</button></td></tr></tbody></table></div><button v-if="cursor" type="button" class="button actions" :disabled="loading" @click="load(true)">โหลดหน่วยงานเพิ่มเติม</button></section><form class="panel" @submit.prevent="save"><h2>{{ edit ? 'แก้ไขหน่วยงาน' : 'เพิ่มหน่วยงาน' }}</h2><div class="field"><label for="unit-code">รหัสหน่วยงาน</label><input id="unit-code" v-model="form.code" required maxlength="50" :disabled="!!edit" /></div><div class="field"><label for="unit-name">ชื่อหน่วยงาน</label><input id="unit-name" v-model="form.name" required maxlength="255" /></div><template v-if="edit"><label><input v-model="form.is_active" type="checkbox" /> เปิดใช้งานหน่วยงาน</label><div class="field inline-reason"><label for="unit-reason">เหตุผลการเปลี่ยนแปลง</label><textarea id="unit-reason" v-model="form.reason" required maxlength="1000" /></div></template><p v-else class="hint">หน่วยงานใหม่จะอยู่ในสถานะรอผู้ดูแล ไปที่จัดการผู้ใช้เพื่อแต่งตั้ง UNIT_ADMIN</p><div class="actions"><button class="button primary" :disabled="saving">{{ saving ? 'กำลังบันทึก…' : 'บันทึกหน่วยงาน' }}</button><button v-if="edit" type="button" class="button" @click="select()">ยกเลิกแก้ไข</button></div></form></div><section class="panel"><h2>Station รับส่งหนังสือ</h2><p class="muted">Station เป็นจุดในเส้นทางหนังสือของหน่วยงานที่เปิดใช้งานแล้ว</p><form class="form-grid actions" @submit.prevent="createStation"><div class="field"><label for="station-unit">หน่วยงาน</label><select id="station-unit" v-model="stationForm.unit_id" required><option disabled value="">เลือกหน่วยงาน</option><option v-for="u in units.filter(u => u.is_active)" :key="u.id" :value="u.id">{{ u.name }}</option></select></div><div class="field"><label for="station-code">รหัส Station</label><input id="station-code" v-model="stationForm.code" required maxlength="50" /></div><div class="field"><label for="station-name">ชื่อ Station</label><input id="station-name" v-model="stationForm.name" required maxlength="255" /></div><div><button class="button primary" :disabled="saving">เพิ่ม Station</button></div></form><ul class="route-steps"><li v-for="s in stations" :key="s.id">{{ s.name }}<small>{{ s.code || s.id }}</small></li></ul></section></template></template>
